/** Complete historical rows, mechanically represented without repeated hashes.
 * Path order and each version's own SHA remain exact; this is not an issuer. */
function historicalBindingDelta(base:readonly {path:string;sha256:string}[],paths:readonly string[],overrides:Readonly<Record<string,string>>):readonly {path:string;sha256:string}[]{
 const values=new Map(base.map(row=>[row.path,row.sha256]));
 if(values.size!==base.length||new Set(paths).size!==paths.length||Object.keys(overrides).some(path=>!paths.includes(path)))throw Error('Invalid complete historical binding delta');
 return Object.freeze(paths.map(path=>{const sha256=Object.prototype.hasOwnProperty.call(overrides,path)?overrides[path]:values.get(path);if(typeof sha256!=='string'||!(/^[0-9a-f]{64}$/u).test(sha256))throw Error('Incomplete historical binding delta');return Object.freeze({path,sha256});}));
}
